import Redis from "ioredis";

/**
 * Stores a per-user "recent activity" feed (notifications / recent events) in Redis.
 * One Redis list per user, newest event at the head.
 */
export class RecentFeedService {
  constructor(private readonly redis: Redis) {}

  private feedKey(userId: string): string {
    return `feed:${userId}`;
  }

  /**
   * Records a new event for the user's feed.
   */
  async addEvent(userId: string, entry: string): Promise<void> {
    // Newest entry goes to the head of the list.
    await this.redis.lpush(this.feedKey(userId), entry);
  }

  /**
   * Returns the user's feed, newest first.
   */
  async getFeed(userId: string): Promise<string[]> {
    // Reads the entire collection, no matter how large it has grown.
    return this.redis.lrange(this.feedKey(userId), 0, -1);
  }
}
